// Apply only at the lead's integration checkpoint. Geography is generated by
// prepare-narvsky-area.mjs; gates by connect-narvsky-areas.mjs.
import fs from 'node:fs';
const id='narvsky';
const {rects}=JSON.parse(fs.readFileSync(`src/areas/${id}/territory.json`,'utf8'));
const row={id,page:'narvsky.html',bake:'baked/narvsky/',requireBake:true,title:'Нарвский',titleEn:'Narvsky',sights:['Нарвские триумфальные ворота','Дворец культуры имени Горького','Площадь Стачек','Екатерингофка и промышленные кварталы'],approxMB:65,dev:false,mapId:73,
remap:{'src/world/data/city.js':`src/areas/${id}/data/city.js`,'src/world/area.js':`src/areas/${id}/area.js`,'src/world/city/known-data.js':`src/areas/${id}/known-data.js`,'src/world/lib/owns-table.js':`src/areas/${id}/owns-table.js`,'src/world/coastalBridges/sites.js':`src/areas/${id}/bridge-sites.js`},play:rects};
let source=fs.readFileSync('src/areas/registry.js','utf8').replace(/\/\/ NARVSKY-AREA-BEGIN[\s\S]*?\/\/ NARVSKY-AREA-END\n?/g,'');
const anchor='/**\n * Gates between areas:';
if(!source.includes(anchor))throw new Error('Missing gate documentation anchor');
source=source.replace(anchor,`// NARVSKY-AREA-BEGIN\nREGISTRY["narvsky"] = ${JSON.stringify(row,null,2)};\n// NARVSKY-AREA-END\n\n${anchor}`);
fs.writeFileSync('src/areas/registry.js',source);
console.log(`Configured ${id}: ${rects.length} territory rectangles. Next: connect-narvsky-areas, owns-table, gen-area-html --area narvsky, intro-draft --update-live.`);
